import { Fragment } from "react";
import type { ReactNode } from "react";
import {
  Section,
  Row,
  Column,
  Link,
  Text,
  Heading,
  Img,
  Body,
  Head as EmailHead,
  Html,
  Preview,
  Tailwind,
} from "react-email";

import { DefaultFonts } from "@/components/email/font-default";
import { createEmailTailwindConfig } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

type BillingTopVariant =
  | "basic"
  | "bordered"
  | "basic-with-payment"
  | "bordered-with-payment"
  | "basic-with-notes"
  | "bordered-with-notes"
  | "basic-full-details"
  | "bordered-full-details";

type BillingInlineVariant =
  | "basic"
  | "bordered"
  | "basic-with-notes"
  | "bordered-with-notes";

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const responsiveStyles = `
  @media only screen and (max-width: 430px) {
    .order-detail-column { display: block !important; width: 100% !important; }
    .order-detail-gap { line-height: 44px !important; }
  }
`;

const textStyle = { fontFamily, margin: 0 } as const;

const EmailShell = ({ children }: { children: ReactNode }) => (
  <>
    <style>{responsiveStyles}</style>
    <Section style={{ backgroundColor: "#f1f5f9", width: "100%" }}>
      <Fragment>
        <Row>
          <Column>&zwj;</Column>
          <Column
            style={{
              backgroundColor: "#fffffe",
              maxWidth: "100%",
              paddingBottom: "44px",
              width: "600px",
            }}
          >
            <Section style={{ width: "100%" }}>
              <Fragment>
                <Row>
                  <Column style={{ padding: "0 24px" }}>
                    <Section style={{ lineHeight: "44px" }}>&zwj;</Section>
                    {children}
                  </Column>
                </Row>
              </Fragment>
            </Section>
          </Column>
          <Column>&zwj;</Column>
        </Row>
      </Fragment>
    </Section>
  </>
);

const Divider = ({ margin = 24 }: { margin?: number }) => (
  <Section style={{ width: "100%" }}>
    <Fragment>
      <Row>
        <Column>
          <Section
            style={{
              backgroundColor: "#d1d5db",
              height: "1px",
              lineHeight: "1px",
              margin: `${margin}px 0`,
            }}
          >
            &zwj;
          </Section>
        </Column>
      </Row>
    </Fragment>
  </Section>
);

const CardMethod = () => (
  <Section>
    <Fragment>
      <Row>
        <Column>
          <Img
            alt=""
            src={emailAsset("icon-card-visa.png")}
            style={{ maxWidth: "100%", verticalAlign: "middle" }}
            width="40"
          />
        </Column>
        <Column style={{ width: "8px" }}>&zwj;</Column>
        <Column
          style={{
            color: "#4b5563",
            fontFamily,
            fontSize: "12px",
            fontWeight: 500,
            lineHeight: "16px",
          }}
        >
          ****6754
        </Column>
        <Column style={{ width: "8px" }}>&zwj;</Column>
        <Column>|</Column>
        <Column style={{ width: "8px" }}>&zwj;</Column>
        <Column>
          <Link
            href="https://example.com"
            style={{
              color: "#4f46e5",
              fontFamily,
              fontSize: "14px",
              lineHeight: "20px",
              textDecoration: "none",
            }}
          >
            Change
          </Link>
        </Column>
      </Row>
    </Fragment>
  </Section>
);

const PaymentMethod = ({
  amount,
  centered = false,
}: {
  amount?: string;
  centered?: boolean;
}) => {
  if (!amount) {
    return <CardMethod />;
  }
  return (
    <Section
      align={centered ? "center" : undefined}
      style={{
        margin: centered ? "0 auto" : undefined,
        width: centered ? undefined : "100%",
      }}
    >
      <Fragment>
        <Row>
          <Column>
            <CardMethod />
          </Column>
          {centered ? (
            <Column
              style={{
                fontFamily,
                fontSize: "12px",
                lineHeight: "16px",
                padding: "0 12px",
              }}
            >
              |
            </Column>
          ) : null}
          <Column
            style={{
              color: "#4b5563",
              fontFamily,
              fontSize: "12px",
              fontWeight: 500,
              lineHeight: "16px",
              textAlign: "right",
            }}
          >
            {amount}
          </Column>
        </Row>
      </Fragment>
    </Section>
  );
};

const DetailText = ({ children }: { children: ReactNode }) => (
  <Text
    style={{
      ...textStyle,
      color: "#4b5563",
      fontSize: "16px",
      lineHeight: "24px",
    }}
  >
    {children}
  </Text>
);

const DetailBlock = ({
  children,
  gap = 0,
  title,
}: {
  children?: ReactNode;
  gap?: number;
  title: string;
}) => (
  <>
    <Heading
      style={{
        ...textStyle,
        color: "#030712",
        fontSize: "14px",
        fontWeight: 600,
        lineHeight: "20px",
      }}
      as="h3"
    >
      {title}
    </Heading>
    {gap > 0 ? (
      <Section style={{ lineHeight: `${gap}px` }}>&zwj;</Section>
    ) : null}
    {children}
  </>
);

const TwoColumnDetails = ({
  left,
  right,
}: {
  left: ReactNode;
  right: ReactNode;
}) => (
  <Section style={{ width: "100%" }}>
    <Fragment>
      <Row>
        <Column
          className="order-detail-column"
          style={{ verticalAlign: "top", width: "254px" }}
        >
          {left}
        </Column>
        <Column
          className="order-detail-column order-detail-gap"
          style={{ width: "44px" }}
        >
          &zwj;
        </Column>
        <Column
          className="order-detail-column"
          style={{ verticalAlign: "top", width: "254px" }}
        >
          {right}
        </Column>
      </Row>
    </Fragment>
  </Section>
);

const AddressColumns = () => (
  <TwoColumnDetails
    left={
      <DetailBlock title="Billing address">
        <DetailText>
          1234 Maplewood Drive
          <br /> Springfield,
          <br /> IL 62704
        </DetailText>
      </DetailBlock>
    }
    right={
      <DetailBlock title="Shipping address">
        <DetailText>
          782 Oceanview Avenue
          <br /> Santa Monica,
          <br /> CA 90401
        </DetailText>
      </DetailBlock>
    }
  />
);

const FedExShipping = () => (
  <>
    <Section>
      <Img
        alt="FedEx"
        src={emailAsset("order-summary/logo-fedex.png")}
        width="78"
      />
    </Section>
    <DetailText>Takes up to 2 working days</DetailText>
  </>
);

const DhlShipping = () => (
  <DetailText>
    DHL
    <br /> Takes up to 2 working days
  </DetailText>
);

const NotesText = ({ splitLine = false }: { splitLine?: boolean }) => (
  <DetailText>
    Ring buzzer for Apt 3B, or call when outside.
    {splitLine ? <br /> : " "}
    Elevator is on the left.
  </DetailText>
);

const SectionGap = ({ bordered }: { bordered: boolean }) =>
  bordered ? (
    <Divider />
  ) : (
    <Section style={{ lineHeight: "44px" }}>&zwj;</Section>
  );

const ShippingDetails = ({
  bordered,
  layout,
  notes,
}: {
  bordered: boolean;
  layout: "top" | "inline";
  notes: boolean;
}) => {
  if (layout === "inline") {
    return (
      <TwoColumnDetails
        left={
          <DetailBlock title="Shipping method">
            {bordered ? <FedExShipping /> : <DhlShipping />}
          </DetailBlock>
        }
        right={
          <DetailBlock gap={8} title="Payment method">
            <PaymentMethod />
          </DetailBlock>
        }
      />
    );
  }
  if (bordered) {
    return (
      <TwoColumnDetails
        left={<DetailBlock title="Shipping method" />}
        right={notes ? <DhlShipping /> : <FedExShipping />}
      />
    );
  }
  return (
    <DetailBlock title="Shipping method">
      <DhlShipping />
    </DetailBlock>
  );
};

const BillingDetailsSection = ({
  layout,
  variant,
}: {
  layout: "top" | "inline";
  variant: BillingTopVariant | BillingInlineVariant;
}) => {
  const bordered = variant.startsWith("bordered");
  const notes = variant.includes("notes") || variant.includes("full-details");
  const payment =
    layout === "top" &&
    (variant.includes("with-payment") || variant.includes("full-details"));
  return (
    <EmailShell>
      {payment ? (
        <>
          <DetailBlock gap={8} title="Payment method">
            <PaymentMethod />
          </DetailBlock>
          <SectionGap bordered={bordered} />
        </>
      ) : null}

      <AddressColumns />
      <SectionGap bordered={bordered} />

      <ShippingDetails bordered={bordered} layout={layout} notes={notes} />

      {(() => {
        if (notes) {
          return (
            <>
              <SectionGap bordered={bordered} />
              {bordered ? (
                <TwoColumnDetails
                  left={<DetailBlock title="Additional notes" />}
                  right={<NotesText />}
                />
              ) : (
                <DetailBlock title="Additional notes">
                  <NotesText splitLine={true} />
                </DetailBlock>
              )}
            </>
          );
        }
        return null;
      })()}
    </EmailShell>
  );
};

interface BillingInline_OrderSummaryBillingInlineProps {
  theme?: EmailTheme;
  variant?: BillingInlineVariant;
}

const BillingInline_OrderSummaryBillingInlineSection = ({
  variant = "basic",
}: Omit<BillingInline_OrderSummaryBillingInlineProps, "theme">) => (
  <BillingDetailsSection layout="inline" variant={variant} />
);

const BillingInline_OrderSummaryBillingInline = ({
  theme = defaultTheme,
  ...props
}: BillingInline_OrderSummaryBillingInlineProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
    </EmailHead>
    <Preview>Order details</Preview>
    <Tailwind config={createEmailTailwindConfig(theme)}>
      <Body className="m-0 bg-background font-sans">
        <BillingInline_OrderSummaryBillingInlineSection {...props} />
      </Body>
    </Tailwind>
  </Html>
);

BillingInline_OrderSummaryBillingInline.PreviewProps = {
  theme: defaultTheme,
  variant: "basic",
} satisfies BillingInline_OrderSummaryBillingInlineProps;

const __BillingInline = BillingInline_OrderSummaryBillingInline;

interface BillingTop_OrderSummaryBillingTopProps {
  theme?: EmailTheme;
  variant?: BillingTopVariant;
}

const BillingTop_OrderSummaryBillingTopSection = ({
  variant = "basic-with-payment",
}: Omit<BillingTop_OrderSummaryBillingTopProps, "theme">) => (
  <BillingDetailsSection layout="top" variant={variant} />
);

const BillingTop_OrderSummaryBillingTop = ({
  theme = defaultTheme,
  ...props
}: BillingTop_OrderSummaryBillingTopProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
    </EmailHead>
    <Preview>Order details</Preview>
    <Tailwind config={createEmailTailwindConfig(theme)}>
      <Body className="m-0 bg-background font-sans">
        <BillingTop_OrderSummaryBillingTopSection {...props} />
      </Body>
    </Tailwind>
  </Html>
);

BillingTop_OrderSummaryBillingTop.PreviewProps = {
  theme: defaultTheme,
  variant: "basic-with-payment",
} satisfies BillingTop_OrderSummaryBillingTopProps;

const __BillingTop = BillingTop_OrderSummaryBillingTop;

export interface BillingOrderSummaryProps {
  theme?: Parameters<typeof __BillingTop>[0]["theme"];
  payment?: boolean;
  notes?: boolean;
  billingPosition?: "top" | "inline";
  appearance?: "plain" | "bordered";
}

const billingVariant = ({
  appearance,
  billingPosition,
  notes,
  payment,
}: Pick<
  BillingOrderSummaryProps,
  "appearance" | "billingPosition" | "notes" | "payment"
>) => {
  const prefix = appearance === "bordered" ? "bordered" : "basic";
  if (billingPosition === "inline") {
    return notes ? `${prefix}-with-notes` : prefix;
  }
  if (notes && payment) {
    return `${prefix}-full-details`;
  }
  if (notes) {
    return `${prefix}-with-notes`;
  }
  return payment ? `${prefix}-with-payment` : prefix;
};

export const BillingOrderSummary = ({
  theme,
  payment,
  notes,
  billingPosition = "top",
  appearance = "plain",
}: BillingOrderSummaryProps) => {
  const variant = billingVariant({
    appearance,
    billingPosition,
    notes,
    payment,
  });
  return billingPosition === "inline" ? (
    <__BillingInline
      theme={theme}
      variant={variant as Parameters<typeof __BillingInline>[0]["variant"]}
    />
  ) : (
    <__BillingTop
      theme={theme}
      variant={variant as Parameters<typeof __BillingTop>[0]["variant"]}
    />
  );
};

BillingOrderSummary.PreviewProps = {
  appearance: "plain",
  billingPosition: "top",
} satisfies BillingOrderSummaryProps;

const ASSET_ORIGIN = "https://www.emailcn.run";
const ICONS8_ORIGIN = "https://img.icons8.com";
const UNSPLASH_ORIGIN = "https://images.unsplash.com";

const portraitIds = [
  "photo-1500648767791-00dcc994a43e",
  "photo-1507003211169-0a1dd7228f2d",
  "photo-1494790108377-be9c29b29330",
  "photo-1438761681033-6461ffad8d80",
  "photo-1534528741775-53994a69daeb",
  "photo-1506794778202-cad84cf45f1c",
] as const;

const productIds = [
  "photo-1521572163474-6864f9cf17ab",
  "photo-1503341504253-dff4815485f1",
  "photo-1576566588028-4147f3842f27",
  "photo-1562157873-818bc0726f68",
] as const;

const socialIconSlugs = {
  discord: "discord-logo",
  facebook: "facebook-new",
  github: "github",
  instagram: "instagram-new",
  linkedin: "linkedin",
  slack: "slack-new",
  x: "twitterx--v1",
  youtube: "youtube-play",
} as const;

const brandIconSlugs = [
  [/(?:btc|bitcoin)/i, "bitcoin--v1"],
  [/(?:eth|ethereum)/i, "ethereum"],
  [/visa/i, "visa"],
  [/mastercard/i, "mastercard-logo"],
  [/apple-pay/i, "apple-pay"],
  [/google-pay/i, "google-pay"],
  [/klarna/i, "klarna"],
  [/stripe/i, "stripe"],
  [/fedex/i, "fedex"],
  [/north-face/i, "the-north-face"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/teams\/member-\d+-lg/i.test(path)) {
    return [800, 560] as const;
  }
  if (/teams\/member-\d+/i.test(path)) {
    return [600, 600] as const;
  }
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

const getIndexedAsset = (path: string, assets: readonly string[]) => {
  const explicitIndex = path.match(
    /(?:member|avatar|product-list|shopping-cart)-(\d+)/i
  )?.[1];
  const index = explicitIndex
    ? Number.parseInt(explicitIndex, 10) - 1
    : hashString(path);

  return assets[((index % assets.length) + assets.length) % assets.length];
};

const getUnsplashAsset = (id: string, width: number, height: number) =>
  `${UNSPLASH_ORIGIN}/${id}?auto=format&fit=crop&w=${width}&h=${height}&q=80`;

const getIcons8Asset = (
  slug: string,
  {
    color,
    style = "ios-filled",
  }: {
    color?: string;
    style?: "color" | "ios" | "ios-filled";
  } = {}
) =>
  color
    ? `${ICONS8_ORIGIN}/${style}/50/${color}/${slug}.png`
    : `${ICONS8_ORIGIN}/${style}/50/${slug}.png`;

const getStoreBadgeAsset = (path: string) => {
  if (/badge-app-store/i.test(path)) {
    return "https://developer.apple.com/assets/elements/badges/download-on-the-app-store.svg";
  }
  if (/badge-google-play/i.test(path)) {
    return "https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png";
  }
};

const getSocialIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  for (const [name, slug] of Object.entries(socialIconSlugs)) {
    if (new RegExp(`(?:^|[-/])${name}(?:[-.]|$)`, "i").test(path)) {
      return getIcons8Asset(slug, { color: foreground });
    }
  }
};

const getUtilityIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  if (/star-half/i.test(path)) {
    return getIcons8Asset("star-half-empty", { color: "374151" });
  }
  if (/star-solid/i.test(path)) {
    return getIcons8Asset("star--v1", { color: "374151" });
  }
  if (/edit/i.test(path)) {
    return getIcons8Asset("edit--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/arrow-right/i.test(path)) {
    return getIcons8Asset("long-arrow-right--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/chevron-right/i.test(path)) {
    return getIcons8Asset("chevron-right", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/check/i.test(path)) {
    return getIcons8Asset("checkmark--v1", { color: foreground });
  }
};

const getBrandIconAsset = (path: string) => {
  const match = brandIconSlugs.find(([pattern]) => pattern.test(path));

  return match
    ? getIcons8Asset(match[1], {
        style: "color",
      })
    : undefined;
};

const getWordmarkAsset = (path: string) => {
  const isLight = /light/i.test(path);
  const background = isLight ? "030712" : "FFFFFF";
  const foreground = isLight ? "FFFFFF" : "111827";

  return `https://placehold.co/320x96/${background}/${foreground}.png?text=EMAILCN`;
};

const getIconAsset = (path: string) =>
  getStoreBadgeAsset(path) ??
  getSocialIconAsset(path) ??
  getUtilityIconAsset(path) ??
  getBrandIconAsset(path);

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const iconAsset = getIconAsset(normalizedPath);
  if (iconAsset) {
    return iconAsset;
  }

  const seed = getSeed(normalizedPath);
  const [width, height] = getDimensions(normalizedPath);

  if (/teams\/hero/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1521737711867-e3b97375f902", width, height);
  }

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, portraitIds),
      width,
      height
    );
  }

  if (/products\/shoe/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1542291026-7eec264c27ff", width, height);
  }

  if (/products\/phone/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1511707171634-5f897ff02aa9", width, height);
  }

  if (
    /(?:product-detail|product-lists|products\/product|shopping-cart)/i.test(
      normalizedPath
    )
  ) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, productIds),
      width,
      height
    );
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (/(?:emailcn|maizzle|logo|insignia)/i.test(normalizedPath)) {
    return getWordmarkAsset(normalizedPath);
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
